import java.util.*;

/** Debug: compare original if-else populate vs data-driven populate, cell by cell. */
public class PopulateDiff
{
    static final int DEPTH = 160, WIDTH = 240, HUNTER_LIMIT = 5;
    static final Map<Class<?>, Double> P = Map.ofEntries(
            Map.entry(Coyote.class, 0.010), Map.entry(Deer.class, 0.080),
            Map.entry(Wolf.class, 0.010), Map.entry(Eagle.class, 0.01),
            Map.entry(Mouse.class, 0.080), Map.entry(Grass.class, 0.030),
            Map.entry(Hunter.class, 0.03));
    static final List<Class<?>> ORDER =
            List.of(Grass.class, Deer.class, Coyote.class, Wolf.class, Eagle.class, Mouse.class, Hunter.class);

    public static void main(String[] a)
    {
        String[][] oldGrid = run(true);
        String[][] newGrid = run(false);
        int diffs = 0;
        for (int r = 0; r < DEPTH; r++)
            for (int c = 0; c < WIDTH; c++)
                if (!Objects.equals(oldGrid[r][c], newGrid[r][c])) {
                    if (diffs < 10)
                        System.out.println("DIFF at (" + r + "," + c + "): old=" + oldGrid[r][c] + " new=" + newGrid[r][c]);
                    diffs++;
                }
        System.out.println("TOTAL DIFFS=" + diffs);
    }

    static String[][] run(boolean original)
    {
        Randomizer.reset();
        Random rand = Randomizer.getRandom();
        Field field = new Field(DEPTH, WIDTH);
        Environment env = new Environment(new Time(), new Weather());
        List<Actor> actors = new ArrayList<>();
        int hunterCount = 0;
        field.clear();
        for (int row = 0; row < DEPTH; row++) {
            for (int col = 0; col < WIDTH; col++) {
                Animal.Gender sex = Randomizer.getRandomSex();
                Location loc = new Location(row, col);
                if (original) {
                    if (rand.nextDouble() <= P.get(Grass.class)) actors.add(new Grass(field, loc));
                    else if (rand.nextDouble() <= P.get(Deer.class)) actors.add(new Deer(true, field, loc, sex));
                    else if (rand.nextDouble() <= P.get(Coyote.class)) actors.add(new Coyote(true, field, loc, sex));
                    else if (rand.nextDouble() <= P.get(Wolf.class)) actors.add(new Wolf(true, field, loc, sex));
                    else if (rand.nextDouble() <= P.get(Eagle.class)) actors.add(new Eagle(true, field, loc, sex));
                    else if (rand.nextDouble() <= P.get(Mouse.class)) actors.add(new Mouse(true, field, loc, sex));
                    else if (rand.nextDouble() <= P.get(Hunter.class)) {
                        if (hunterCount < HUNTER_LIMIT) { actors.add(new Hunter(field, loc, env)); hunterCount++; }
                    }
                } else {
                    for (Class<?> sp : ORDER) {
                        if (rand.nextDouble() <= P.get(sp)) {
                            Actor actor = null;
                            if (sp == Grass.class) actor = new Grass(field, loc);
                            else if (sp == Deer.class) actor = new Deer(true, field, loc, sex);
                            else if (sp == Coyote.class) actor = new Coyote(true, field, loc, sex);
                            else if (sp == Wolf.class) actor = new Wolf(true, field, loc, sex);
                            else if (sp == Eagle.class) actor = new Eagle(true, field, loc, sex);
                            else if (sp == Mouse.class) actor = new Mouse(true, field, loc, sex);
                            else if (sp == Hunter.class) {
                                if (hunterCount < HUNTER_LIMIT) { actor = new Hunter(field, loc, env); hunterCount++; }
                            }
                            if (actor != null) actors.add(actor);
                            break;
                        }
                    }
                }
            }
        }
        String[][] grid = new String[DEPTH][WIDTH];
        for (int r = 0; r < DEPTH; r++)
            for (int c = 0; c < WIDTH; c++) {
                Object o = field.getObjectAt(r, c);
                grid[r][c] = o == null ? null : o.getClass().getSimpleName();
            }
        return grid;
    }
}

